const freeDomains = new Set(['gmail.com','googlemail.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com','me.com','proton.me','protonmail.com']);
const seniorTerms = ['ceo','cto','cio','coo','cdo','chief','director','directora','vp','vice president','gerente','head','presidente','president','owner','fundador','founder'];
const strategicInterests = new Set(['Inteligencia Artificial','Automatización','Software Empresarial','LCH Evidence AI']);
return $input.all().map((item) => {
  const lead = item.json;
  let score = 0;
  const reasons = [];
  const email = String(lead.email ?? '').trim().toLowerCase();
  const domain = email.split('@')[1] ?? '';
  const role = String(lead.cargo ?? '').toLowerCase();
  const interest = String(lead.interes ?? '');
  const message = String(lead.mensaje ?? '').trim();
  const company = String(lead.empresa ?? '').trim();
  if (domain && !freeDomains.has(domain)) { score += 2; reasons.push('corporate_email'); }
  if (seniorTerms.some((term) => role.includes(term))) { score += 3; reasons.push('decision_maker_role'); }
  if (strategicInterests.has(interest)) { score += 2; reasons.push('strategic_interest'); }
  if (message.length >= 20) { score += 2; reasons.push('described_operational_challenge'); }
  if (company.length >= 3) { score += 1; reasons.push('company_identified'); }
  const priority = score >= 7 ? 'HOT' : score >= 4 ? 'WARM' : 'LOW';
  const queue = priority === 'HOT' ? 'sales_immediate' : priority === 'WARM' ? 'sales_standard' : 'sales_nurture';
  const slaMinutes = priority === 'HOT' ? 15 : priority === 'WARM' ? 240 : 1440;
  return { json: { ...lead, automationStatus: 'processed', automationPriority: priority, automationScore: score, automationReasons: reasons, automationQueue: queue, automationSlaMinutes: slaMinutes, automationProcessedAt: new Date().toISOString() } };
});
